import{_ as t,a as r,o as a,a6 as n}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"List Return Reasons","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-return-reasons","title":"List Return Reasons","description":"List the active reasons a customer can pick when raising a return, filtered by resolution type.","query":"query ReturnReasons($resolutionType: String!) {\\n  returnReasons(resolutionType: $resolutionType) {\\n    _id\\n    title\\n    position\\n  }\\n}\\n","variables":"{\\n  \\"resolutionType\\": \\"return\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"returnReasons\\": [\\n      {\\n        \\"_id\\": 2,\\n        \\"title\\": \\"Damaged product\\",\\n        \\"position\\": 1\\n      },\\n      {\\n        \\"_id\\": 3,\\n        \\"title\\": \\"Wrong item delivered\\",\\n        \\"position\\": 2\\n      },\\n      {\\n        \\"_id\\": 4,\\n        \\"title\\": \\"No longer needed\\",\\n        \\"position\\": 3\\n      }\\n    ]\\n  }\\n}\\n","commonErrors":[{"error":"resolutionType required","cause":"The resolutionType argument is missing or not one of return / cancel_items","solution":"Provide a valid resolutionType — either \\"return\\" or \\"cancel_items\\""},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/queries/list-return-reasons.md","filePath":"api/graphql-api/shop/returns/queries/list-return-reasons.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/shop/returns/queries/list-return-reasons.md"};function s(i,e,d,u,l,c){return a(),r("div",null,e[0]||(e[0]=[n('<h1 id="list-return-reasons" tabindex="-1">List Return Reasons <a class="header-anchor" href="#list-return-reasons" aria-label="Permalink to &quot;List Return Reasons&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>returnReasons</code> query lists the active reasons a customer can pick when raising a return, filtered by the resolution type. Use a reason&#39;s <code>_id</code> as the <code>rmaReasonId</code> when calling <a href="/api/graphql-api/shop/returns/mutations/create-return.html"><code>createCustomerReturn</code></a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>resolutionType</code></td><td><code>String!</code></td><td>✅ Yes</td><td>The resolution the reasons apply to — <code>return</code> or <code>cancel_items</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><p>The query returns a plain list of reasons, not a cursor connection — there is no <code>edges</code>, <code>pageInfo</code>, or <code>totalCount</code> to select, and no pagination arguments. Every active reason for the resolution type comes back in one response.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>Int!</code></td><td>Numeric reason id — use as <code>rmaReasonId</code> when raising a return.</td></tr><tr><td><code>title</code></td><td><code>String!</code></td><td>Reason label, e.g. <code>Damaged product</code>.</td></tr><tr><td><code>position</code></td><td><code>Int!</code></td><td>Display order position.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a></li><li><a href="/api/graphql-api/shop/returns/mutations/create-return.html">Raise a Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',12)]))}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
